// Generated by tools/bundle.py from problems/convolution/bitwise_xor_convolution/solution.cpp. Edit that file instead.
// c_k = sum of a_i b_j over i xor j = k, mod 998244353, for 2^N terms (N <= 20).
// c = H (H a . H b) / 2^N, H the Walsh-Hadamard transform. The transforms run on signed 64-bit
// lanes: a level at most doubles |x|, so values stay below 2^20 P < 2^50 and no level reduces.
// Design and measurements: notes.md.
//
// Layout: the 2^N values are 2^H rows of 2^L (L = min(N, 12)). A row is 2^(L-2) vectors of four
// int64; rows are S = 2^(L-2) + 2 vectors apart, so the rows of a column fall in different cache
// sets. Within each group of four vectors the forward transform leaves the values transposed
// (vector bits 0-1 <-> lane bits); the inverse transposes back.
//
// Order: a's rows as it is parsed, a's columns, a / 2^N mod P kept as dwords; then b in the same
// array: rows, columns, the products with a, the inverse columns; the inverse rows, printed in
// chunks. Each int64 array is transformed while it is still in the cache.
// lib/io/bulk32.hpp
// Bulk read of uint32 arrays with AVX2, on top of io::Reader:
//
//   io::Reader in;
//   io::read_bulk(in, a.data(), n);  // same values as in.read(a.data(), n); faster on Zen 3
//
// On Zen 3 (the judge's CPU) it uses BulkParser32 below; elsewhere it is Reader::read, which is
// faster there. -DIO_BULK32_TRANSPOSE=0 or 1 forces either. Kept apart from io.hpp so that the
// code of the programs that do not need it stays unchanged. Design and measurements:
// lib/io/notes.md.

// lib/io/io.hpp
// Fast integer and text I/O on file descriptors (stdin and stdout by default).
// Linux, x86-64 with AVX2. Design and measurements: lib/io/notes.md.
//
//   io::Reader in;                            // takes all of stdin
//   io::Writer out;                           // flushes in its destructor
//   const auto n = in.read<std::uint32_t>();
//   std::vector<std::uint32_t> a(n);
//   in.read(a.data(), n);                     // bulk; AVX2 for uint32_t
//   const auto s = in.read<std::uint64_t, 16>();  // promise: at most 16 digits (faster)
//   out.write("n = ", n, '\n');               // any mix of integers, chars, strings
//   out.write<16>(s, '\n');                   // promise: integers of at most 16 digits
//   out.write_array(a.data(), n, ' ');        // bulk; AVX2 for uint32_t
//   out.write('\n');
//
// Input: tokens separated by whitespace (any bytes <= ' '). Integer tokens are an optional '-'
// (signed types only) followed by decimal digits, and fit the requested type. Reading past the
// last token is undefined. The 64 bytes before the input and after its end are readable zeros, so
// custom parsers may load up to 64 bytes around any token from word().

